const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let locations=['Recebimento 1','Sala de embalagem','Estoque','Freezer 1','Freezer da cozinha'],flavors=['Morango','Maracujá','Limão'],states=['Líquido','Congelado'],skus=flavors.map((f,i)=>({code:'YOL-00'+(i+1),flavor:f})),boxes=[],notes=[],packages=[{id:'PRETA-001',location:'Fábrica'},{id:'PRETA-002',location:'Recebimento 1'}],history=[],view='Inventário',filter='',stateFilter='',seq=10;
const mk=(id,flavor,qty,loc,grade,state='Líquido',active=false)=>({id,flavor,qty,loc,grade,state,active,lot:'L260901',date:'2026-09-01',analysis:!grade});
boxes=[mk('CX-001','Morango',100,2,'AAA'),mk('CX-002','Morango',100,2,'AAA'),mk('CX-003','Morango',35,1,'AAA','Líquido',true),mk('CX-004','Maracujá',100,3,'B','Congelado'),mk('CX-005','Maracujá',42,3,'B','Congelado',true),mk('CX-006','Limão',235,0,'')];
const navs=['Início','Inventário','Notas fiscais','Embalagens','Cadastros','Movimentações'],icons=['⌂','▦','▤','▣','⚙','↔'];
function go(v){view=v;render()}function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3500)}function log(t){history.unshift({t,at:new Date().toLocaleTimeString('pt-BR'),user:'Operador demo'})}function opts(a,selected){return a.map((x,i)=>`<option value="${i}" ${i===selected?'selected':''}>${esc(x)}</option>`).join('')}function input(name,title,value='',type='text'){return `<label>${title}<input name="${name}" type="${type}" value="${esc(value)}" required ${type==='number'?'min="0" step="1"':''}></label>`}function select(name,title,a,selected=0){return `<label>${title}<select name="${name}">${opts(a,selected)}</select></label>`}
function openForm(title,html,submit){$('title').textContent=title;$('fields').innerHTML=html;$('error').textContent='';$('form').onsubmit=e=>{e.preventDefault();try{submit(Object.fromEntries(new FormData(e.target)));$('modal').close();render();toast('Registrado no protótipo')}catch(err){$('error').textContent=err.message}};$('modal').showModal()}
function render(){ $('nav').innerHTML=navs.map((n,i)=>`<button class="${view===n?'active':''}" onclick="go('${n}')">${icons[i]} &nbsp; ${n}</button>`).join('');let html=`<div class="heading"><div><h1>${view}</h1><p>YOLO · controle de estoque e recebimento</p></div><button class="primary" onclick="receive()">＋ Novo recebimento</button></div>`;
if(view==='Início'){html+='<div class="notice">Ambiente de demonstração. Sem login real, integrações ou salvamento permanente.</div><div class="tiles">'+navs.slice(1).map((n,i)=>`<button class="tile" onclick="go('${n}')"><span>${icons[i+1]}</span>${n}<small>${['Consultar caixas e movimentar pops','Consultar recebimentos registrados','Acompanhar caixas retornáveis','Produtos, sabores, estados e locais','Histórico das operações'][i]}</small></button>`).join('')+'</div>'}
if(view==='Inventário'){const total=boxes.reduce((s,b)=>s+b.qty,0),pending=boxes.filter(b=>b.analysis).reduce((s,b)=>s+b.qty,0);html+=`<div class="stats">${[[total,'Pops no estoque'],[pending,'Em análise'],[boxes.filter(b=>!b.analysis&&!b.blocked&&!b.awaitingPacking&&b.qty===100).length,'Caixas completas'],[boxes.filter(b=>b.active).length,'Caixas de separação']].map(([v,l])=>`<div class="stat"><span>${l}</span><strong>${v.toLocaleString('pt-BR')}</strong></div>`).join('')}</div><div class="toolbar"><input aria-label="Buscar caixa ou sabor" placeholder="Buscar caixa, sabor ou lote…" value="${esc(filter)}" oninput="filter=this.value;renderBoard()"><select aria-label="Filtrar estado" onchange="stateFilter=this.value;renderBoard()"><option value="">Todos os estados</option>${states.map(s=>`<option ${s===stateFilter?'selected':''}>${esc(s)}</option>`).join('')}</select><button onclick="scan()">⌕ Buscar por código</button></div><div id="board" class="board"></div>`}
if(view==='Notas fiscais')html+='<div class="panel"><h2>Notas fiscais de recebimento</h2>'+ (notes.length?notes.map(n=>`<div class="row"><div><strong>NF ${esc(n.nf)} · ${esc(n.supplier)}</strong><small>${esc(n.date)} · ${esc(n.lot)} · ${n.qty} unidades · ${esc(n.pkg)}</small></div><span class="tag">Recebida</span></div>`).join(''):'<p>Nenhuma nota registrada nesta sessão. Use Novo recebimento para começar.</p>')+'</div>';
if(view==='Embalagens')html+='<div class="panel"><h2>Caixas pretas · circuito da fábrica</h2>'+packages.map((p,i)=>`<div class="row"><div><strong>${esc(p.id)}</strong><small>${esc(p.location)}</small></div><button onclick="packageMove(${i})">Movimentar</button></div>`).join('')+'</div><div class="panel"><h2>Caixas médias · conteúdo atual</h2>'+boxes.filter(b=>!b.analysis).map(b=>`<div class="row"><div><strong>${esc(b.id)}</strong><small>${esc(b.flavor)} · ${b.qty} pops · ${esc(locations[b.loc])}</small></div><button onclick="detail('${b.id}')">Abrir</button></div>`).join('')+'</div>';
if(view==='Cadastros')html+=['Locais','Sabores','Estados','SKUs'].map(type=>{const a=type==='Locais'?locations:type==='Sabores'?flavors:type==='Estados'?states:skus.map(s=>s.code+' · '+s.flavor);return `<div class="panel"><div class="row"><h2>${type}</h2><button onclick="addMaster('${type}')">＋ Adicionar</button></div>${a.map((x,i)=>`<div class="row"><span>${esc(x)}</span>${type==='Locais'?`<button onclick="renameLocation(${i})">Renomear</button>`:''}</div>`).join('')}</div>`}).join('')+'<div class="panel"><h2>Classificações</h2><p>AAA · Exportação, e-commerce e varejo<br>B · Eventos e revenda em freezers<br>C · Amostras e consumo da equipe</p><p>Fotos e documentos de referência: previstos para a versão conectada.</p></div>';
if(view==='Movimentações')html+='<div class="panel"><h2>Histórico desta sessão</h2>'+(history.length?history.map(h=>`<div class="row"><div>${esc(h.t)}<small>${h.at} · ${h.user}</small></div></div>`).join(''):'<p>As operações realizadas aqui aparecerão nesta lista.</p>')+'</div>';
$('app').innerHTML=html;if(view==='Inventário')renderBoard()}
function renderBoard(){const list=boxes.filter(b=>b.qty>0&&(b.id+' '+b.flavor+' '+b.lot).toLowerCase().includes(filter.toLowerCase())&&(!stateFilter||b.state===stateFilter));$('board').innerHTML=locations.map((l,i)=>{const bs=list.filter(b=>b.loc===i);return `<section class="column"><div class="colhead">${esc(l)} <span>${bs.length}</span></div>${bs.map(b=>`<article class="card" tabindex="0" role="button" onclick="detail('${b.id}')" onkeydown="if(event.key==='Enter')detail('${b.id}')"><div class="cardtop"><span>${b.id}</span><span>${b.awaitingPacking?'A ENCAIXOTAR':b.analysis?'GRANEL':b.active?'SEPARAÇÃO':b.qty===100?'COMPLETA':'PARCIAL'}</span></div><h3>${esc(b.flavor)}</h3><div class="tags"><span class="tag ${b.grade}">${b.grade||'Em análise'}</span><span class="tag">${esc(b.state)}</span></div><div class="qty"><strong>${b.qty} <small>pops</small></strong><small>${b.analysis?'Classificar →':'Abrir caixa →'}</small></div><div class="boxmeta">${esc(b.lot)} · ${b.date}</div></article>`).join('')||'<div class="empty">Nenhuma caixa neste local</div>'}</section>`}).join('')}
function receive(){openForm('Novo recebimento',input('nf','Número da nota fiscal')+input('supplier','Fornecedor')+input('date','Data de recebimento','2026-09-09','date')+input('lot','Lote')+select('flavor','Sabor',flavors)+input('qty','Quantidade declarada',235,'number')+input('pkg','Código da caixa preta (leitor ou digitação)','PRETA-001')+'<p>Entrada em Recebimento 1, em análise. Neste protótipo, um sabor e uma caixa por recebimento.</p>',d=>{if(+d.qty<1)throw Error('Informe uma quantidade positiva.');notes.push({...d});boxes.push({...mk(uniqueStockId('CX-'),flavors[+d.flavor],+d.qty,0,''),lot:d.lot,date:d.date});let p=packages.find(p=>p.id===d.pkg);if(p)p.location=locations[0];else packages.push({id:d.pkg,location:locations[0]});log(`Recebimento NF ${d.nf}: ${d.qty} pops em análise`);view='Inventário'})}
function detail(id){const b=boxes.find(b=>b.id===id);if(!b)return;if(b.analysis){openForm('Classificar · '+id,`<p>${esc(b.flavor)} · declarado: ${b.qty} pops. Confirme limpeza e contagem ao concluir.</p>`+input('AAA','AAA',b.qty,'number')+input('B','B',0,'number')+input('C','C',0,'number')+input('reason','Observação da contagem','Contagem conferida'),d=>{const sum=+d.AAA + +d.B + +d.C;if(sum!==b.qty)throw Error('Nesta demonstração, a soma deve corresponder ao recebimento. Divergências exigirão conciliação na versão completa.');boxes=boxes.filter(x=>x.id!==id);for(const grade of ['AAA','B','C']){let n=+d[grade];while(n>0){const q=Math.min(100,n);boxes.push({...b,id:uniqueStockId('CX-'),qty:q,grade,analysis:false,loc:1,active:false});n-=q}}log(`Classificação ${id}: AAA ${d.AAA}, B ${d.B}, C ${d.C}. ${d.reason}`)});return}
openForm(b.id+' · '+b.flavor,`<p>${b.qty} pops · ${b.grade} · ${esc(b.lot)}</p>`+select('loc','Transferir para',locations,b.loc)+select('state','Estado confirmado',states,states.indexOf(b.state))+select('active','Caixa de separação',['Não','Sim'],b.active?1:0)+input('withdraw','Retirar unidades',0,'number')+'<p>Transferir para um freezer não altera automaticamente o estado. Retiradas são simulações, sem pedido ou faturamento.</p>',d=>{const q=+d.withdraw,newState=states[+d.state],active=d.active==='1';if(q>b.qty)throw Error('Quantidade maior que o saldo.');if(q&&!active)throw Error('Use uma caixa de separação para retirar unidades.');if(active&&boxes.some(x=>x.id!==id&&x.active&&x.flavor===b.flavor&&x.state===newState))throw Error('Já existe uma caixa de separação para este sabor e estado.');const old=locations[b.loc];Object.assign(b,{loc:+d.loc,state:newState,active,qty:b.qty-q});if(!b.qty)b.active=false;log(`${id}: ${old} → ${locations[b.loc]}; ${newState}; retirada ${q}; saldo ${b.qty}`)})}
function scan(){openForm('Buscar por código',input('code','Código da caixa','CX-001'),d=>{if(!boxes.some(b=>b.id===d.code))throw Error('Caixa não encontrada.');setTimeout(()=>detail(d.code),0)})}
function packageMove(i){openForm('Movimentar '+packages[i].id,select('loc','Destino',['Fábrica',...locations]),d=>{packages[i].location=['Fábrica',...locations][+d.loc];log(`${packages[i].id} → ${packages[i].location}`)})}
function renameLocation(i){openForm('Renomear local',input('name','Nome',locations[i]),d=>{const n=d.name.trim();if(!n||locations.some((x,j)=>j!==i&&x===n))throw Error('Use um nome único.');const old=locations[i];locations[i]=n;packages.forEach(p=>{if(p.location===old)p.location=n});log(`Local ${old} renomeado para ${n}`)})}
function addMaster(type){openForm('Cadastrar · '+type,input('name',type==='SKUs'?'Código SKU':'Nome')+(type==='SKUs'?select('flavor','Sabor',flavors):''),d=>{const n=d.name.trim();if(!n)throw Error('Informe um nome.');if(type==='SKUs'){if(skus.some(s=>s.code===n))throw Error('SKU já cadastrado.');skus.push({code:n,flavor:flavors[+d.flavor]})}else{const a=type==='Locais'?locations:type==='Sabores'?flavors:states;if(a.includes(n))throw Error('Já cadastrado.');a.push(n)}log(`Cadastro ${type}: ${n}`)})}
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'open_inventory_box',description:'Open an existing inventory box form; does not save changes.',inputSchema:{type:'object',properties:{boxId:{type:'string'}},required:['boxId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({boxId})=>{if(!boxes.some(b=>b.id===boxId))throw Error('Unknown box');detail(boxId);return {opened:boxId}}})}catch{}}
render();
